import { CacheManager } from './cache-manager.js';
import { getRemoteCommitSha } from './git.js';
import * as fs from 'fs';
import * as path from 'path';
import os from 'os';

// This is a minimal mock analysis result for demonstration
// In reality, this would be generated by a full LSP analysis
const generateMockResult = (repoName: string) => ({
  nodes: [
    {
      id: "root-file",
      type: "file",
      position: { x: 0, y: 0 },
      data: {
        label: `index.ts`,
        filePath: "src/index.ts",
        nodeType: "file",
        metadata: { lineCount: 100, exportCount: 2, maxComplexity: 5 }
      }
    }
  ],
  edges: [],
  analysis: {
    godObjects: [],
    deadCode: [],
    cycles: [],
    patterns: []
  },
  entryPoint: {
    entryFile: "src/index.ts",
    framework: "node"
  }
});

async function seed() {
  const reposToSeed = [
    'https://github.com/expressjs/express',
    'https://github.com/fastify/fastify',
    'https://github.com/colinhacks/zod'
  ];

  for (const url of reposToSeed) {
    const repoId = url.replace(/^https?:\/\/(www\.)?github\.com\//, '').replace(/\/$/, '');
    console.log(`Seeding cache for ${repoId}...`);
    
    const sha = getRemoteCommitSha(url);
    if (!sha) {
      console.warn(`Could not fetch SHA for ${repoId}, skipping.`);
      continue;
    }

    console.log(`Latest SHA: ${sha}`);
    
    // Check if we already have it
    const existing = CacheManager.getLastCommit(repoId);
    if (existing === sha) {
      console.log(`Cache already up-to-date for ${repoId}.`);
      continue;
    }

    const mockResult = generateMockResult(repoId);
    CacheManager.saveResult(repoId, url, sha, mockResult);
    console.log(`Successfully seeded ${repoId}.`);
  }
}

seed().catch(console.error);
